window.__finlexDocLoaded(10148,{"id":10148,"articles":[{"id":1000585,"no":"Overview","heading":"Scope & Key Requirements (Public Summary)","text":"Authoritative international guidance on the arm's length principle, comparability analysis, transfer pricing methods (CUP, RPM, CPLM, TNMM, Profit Split), intangibles, intra-group services, and Country-by-Country Reporting (CbCR).","seq":0},{"id":1000586,"no":"OECD TPG Ch. I–X","heading":"Arm's Length Principle, Five TP Methods, DEMPE & Documentation","text":"• Arm's Length Principle (Chapter I, MTC Art. 9): controlled transactions between associated enterprises must reflect conditions that independent enterprises would agree to.\n• Five Transfer Pricing Methods (Chapter II): Traditional Transaction Methods (CUP, Resale Price, Cost Plus) and Transactional Profit Methods (TNMM, Transactional Profit Split).\n• Intangibles & DEMPE (Chapter VI): profit allocation follows Development, Enhancement, Maintenance, Protection, and Exploitation (DEMPE) functions rather than mere legal ownership.\n• Three-Tier Documentation (Chapter V / BEPS Action 13): Master File, Local File, and Country-by-Country Report (CbCR for groups ≥ EUR 750m).","seq":1},{"id":1000587,"no":"Official Access","heading":"Official Handbook & Reference Entry","text":"Official source (OECD): https://www.oecd.org/en/topics/sub-issues/transfer-pricing.html\nStatus: in_force. Detailed paragraph-level summaries and practice notes can be expanded incrementally.","seq":2}]});
